def clean(df):
    df = df.copy()
    # Remove exact duplicate rows
    df = df.drop_duplicates()
    # Fix Category label variants
    df['Category'] = df['Category'].str.strip().str.title().replace({
        'Office Supplies': 'Office Supplies'
    })
    # Map common title-case back to proper form
    cat_map = {
        'Electronics': 'Electronics',
        'Accessories': 'Accessories',
        'Furniture': 'Furniture',
        'Office Supplies': 'Office Supplies'
    }
    df['Category'] = df['Category'].map(lambda x: cat_map.get(x, x))
    return df

def answer(df):
    df = clean(df)
    counts = df.groupby('Category').size()
    return {str(k): int(v) for k, v in counts.items()}
